/**
 * Route paths of the Copilot / AI credits screens. `typedRoutes` types are generated by
 * `expo start`, so a freshly added route is cast with `as never` at the call site (same as
 * `router.replace('/profile' as never)`), which stays valid once the types are regenerated.
 */
export const COPILOT_ROUTE = '/business-copilot';
export const AI_CREDITS_ROUTE = '/business-ai-credits';

export type CopilotRouteParams = { threadId?: string; q?: string };

/** Router arguments that open Copilot: the latest conversation, a given one, or a new chat with `q`. */
export function copilotHref(params: CopilotRouteParams = {}) {
  const query: Record<string, string> = {};
  if (params.threadId) query.threadId = params.threadId;
  if (params.q) query.q = params.q;
  return { pathname: COPILOT_ROUTE, params: query } as never;
}
